/**
 * Снимок игры, каким его печатает `cli.py face` (ADR-0019, спека #89).
 *
 * Договор модуля с командой игры. Слова и числа считает команда; модуль
 * рисует их как получил. Имена ключей — те же, что в JSON команды.
 */
export type Face = {
  /** Игровая ли сессия. Вне её Лица нет: остальные поля пусты. */
  is_game: boolean
  /** Строки Полосы: первая — квест и акт, вторая — задание. */
  next: string[]
  /** Ранг словом. */
  rank: string
  /** Сколько квестов закрыто. */
  quests_closed: number
  /** Фраза, которую игра предлагает сказать; пустая строка — фразы нет. */
  say: string
  /** Подпись всплывающего «квест закрыт»; пустая строка — не показывать. */
  toast_quest: string
  /** Подпись всплывающего о ранге этого снимка; пустая строка — не показывать. */
  toast_rank: string
  /**
   * Отпечаток раздела системного промпта с контрактом игры; пустая строка —
   * раздела нет. Сменился — модуль перечитывает раздел (`contract --section`);
   * до модели доходит тот, что был на первом запросе сессии.
   */
  contract: string
}

/** Раздел с контрактом, каким его печатает `cli.py contract --section`. */
export type Voice = {
  /** Отпечаток текста — тот же, что несёт снимок. */
  stamp: string
  /** Текст раздела целиком: заголовок, по которому его узнают скиллы, и контракт. */
  text: string
}

/**
 * Инструмент игры, каким его печатает `cli.py tools` (#93): перечень — список
 * таких записей. Слова и состав считает команда; модуль объявляет движку то,
 * что получил, и зовёт `cli.py tool <name>` со значениями входа.
 */
export type GameTool = {
  /** Имя инструмента; его видит человек рядом с вызовом. */
  name: string
  /** Что инструмент делает — для модели и для списка инструментов. */
  description: string
  /** Схема входа, как её ждёт движок. */
  inputSchema: Record<string, unknown>
  /** Имена значений входа по порядку: так они встают в вызов команды. */
  input: string[]
}

declare module 'claude-code' {
  interface PluginState {
    jedicoder: {
      /** Последний снимок; null — рисовать нечего. */
      face: Face | null
      /** В этой сессии позвана команда игры. */
      called: boolean
      /** Игровая ли сессия по последнему снимку. Верно и там, где Полосе рисовать нечего. */
      game: boolean
      /** Фраза игры, уже вставшая в поле ввода; пустая строка — ни одна не стоит. */
      said: string
      /** Раздел с контрактом для системного промпта; null — раздела нет. */
      voice: Voice | null
      /**
       * Свежий снимок для системного промпта: `none` — ещё не нужен, `due` —
       * человек прислал запрос и промпт ждёт снимка, `done` — уже перечитан.
       */
      look: 'none' | 'due' | 'done'
      /**
       * Инструменты игры, которые модуль обслуживает; пусто — инструментов нет.
       * Значения нет вовсе — память сессии стёрта, перечень спрашивается заново.
       */
      tools: GameTool[]
      /**
       * Память сессии заполнена: старт прошёл или память возвращена после
       * стирания (`/clear`). Значения нет — её пора вернуть.
       */
      awake: boolean
    }
  }
}
